object FeatureFlags {
    // Swapped to the actual modules named in the Motion Studio master
    // prompt (not the screenshot's After Motion feature names). All true
    // = nothing shown as locked; flip a specific one back to false if it
    // genuinely isn't ready in 3 weeks.
    const val NODE_COMPOSITOR_ENABLED = true      // Module 2.3 — DaVinci-style node graph
    const val VELOCITY_CURVE_EDITOR_ENABLED = true // Module 2.2 — After Effects-style graph editor
    const val AI_COPILOT_ENABLED = true            // Module 2.1 — beat-sync/auto-cut assistant
    const val CUSTOM_SHADERS_ENABLED = true        // Module 2.4 — Alight Motion-style GLSL/expressions
    const val SMART_CUTOUT_ENABLED = true          // Module 2.1 — NPU-accelerated chroma/subject isolation
    const val LUT_IMPORT_ENABLED = true            // Module 2.3 — .cube LUT import + scopes
    const val TEMPLATES_ENABLED = true             // Module 2.1 — .msfx template save/apply
}

object ProjectLimits {
    // No cap — guest mode and logged-in mode behave identically.
    val MAX_PROJECTS: Int? = null // null = unlimited
}

enum class Screen { HOME, EDITOR }

@Composable
fun HomeScreen(onNewProject: () -> Unit, onOpenProject: (String) -> Unit) {
    val recentProjects = remember { mutableStateListOf<String>() }

    Column(modifier = Modifier.fillMaxSize().padding(16.dp)) {
        Text(text = "New Project", style = MaterialTheme.typography.titleMedium)
        Card(modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp)) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text(text = "Unlimited projects")
                Button(onClick = onNewProject) { Text("Create") }
            }
        }

        Text(text = "Recent Projects", style = MaterialTheme.typography.titleMedium)
        if (recentProjects.isEmpty()) {
            Text(text = "No projects yet. Tap 'New Project' to start!")
        } else {
            recentProjects.forEach { name ->
                Card(modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)) {
                    Text(text = name, modifier = Modifier.padding(16.dp))
                }
            }
        }

        // Intentionally no WhatsNewDialog / CommunityUpdateDialog calls here.
        // Login/Sign up can still live in Settings, but nothing in this
        // screen blocks or gates project creation on it.
    }
}

