// =====================================================================
// SECTION 2 — VELOCITY CURVE ENGINE (Phase 0/1)
// =====================================================================

data class BezierHandle(
    val outX: Float = 0.33f,
    val outY: Float = 0.33f,
    val inX: Float = 0.66f,
    val inY: Float = 0.66f,
)

enum class InterpolationType { LINEAR, EASE_IN, EASE_OUT, EASE_IN_OUT, HOLD, CUSTOM_BEZIER }

data class CurvePoint(
    val time: Long,
    val value: Float,
    val interpolation: InterpolationType = InterpolationType.LINEAR,
    val handle: BezierHandle = BezierHandle(),
)

object VelocityCurve {

    fun evaluate(points: List<CurvePoint>, timeMs: Long): Float? {
        if (points.isEmpty()) return null
        if (points.size == 1) return points[0].value
        if (timeMs <= points.first().time) return points.first().value
        if (timeMs >= points.last().time) return points.last().value

        val i = points.indexOfLast { it.time <= timeMs }
        val a = points[i]
        val b = points[i + 1]
        val span = (b.time - a.time).toFloat()
        if (span <= 0f) return a.value
        val t = (timeMs - a.time) / span

        return when (a.interpolation) {
            InterpolationType.HOLD -> a.value
            InterpolationType.LINEAR -> lerp(a.value, b.value, t)
            InterpolationType.EASE_IN -> lerp(a.value, b.value, easeIn(t))
            InterpolationType.EASE_OUT -> lerp(a.value, b.value, easeOut(t))
            InterpolationType.EASE_IN_OUT -> lerp(a.value, b.value, easeInOut(t))
            InterpolationType.CUSTOM_BEZIER -> lerp(a.value, b.value, cubicBezier(t, a.handle))
        }
    }

    private fun lerp(a: Float, b: Float, t: Float) = a + (b - a) * t
    private fun easeIn(t: Float) = t * t
    private fun easeOut(t: Float) = 1f - (1f - t) * (1f - t)
    private fun easeInOut(t: Float) =
        if (t < 0.5f) 2f * t * t else 1f - (-2f * t + 2f).let { it * it } / 2f

    private fun cubicBezier(t: Float, h: BezierHandle, precision: Int = 8): Float {
        var lo = 0f
        var hi = 1f
        var mid = t
        repeat(precision) {
            mid = (lo + hi) / 2f
            val x = bezierComponent(mid, 0f, h.outX, h.inX, 1f)
            if (x < t) lo = mid else hi = mid
        }
        return bezierComponent(mid, 0f, h.outY, h.inY, 1f)
    }

    private fun bezierComponent(t: Float, p0: Float, p1: Float, p2: Float, p3: Float): Float {
        val u = 1f - t
        return u * u * u * p0 + 3f * u * u * t * p1 + 3f * u * t * t * p2 + t * t * t * p3
    }
}

