// =====================================================================
// SECTION 4 — NODE-BASED COMPOSITOR (Phase 2)
// =====================================================================

enum class NodeType { MEDIA_IN, COLOR_WHEEL, MEDIA_OUT }

data class NodePort(val id: String, val name: String, val isInput: Boolean)

data class GraphNode(
    val id: String,
    val type: NodeType,
    val label: String,
    val inputs: List<NodePort>,
    val outputs: List<NodePort>,
    val params: Map<String, Float> = emptyMap(),
)

data class NodeConnection(
    val fromNodeId: String,
    val fromPortId: String,
    val toNodeId: String,
    val toPortId: String,
)

class NodeGraph(
    private val nodes: MutableMap<String, GraphNode> = linkedMapOf(),
    private val connections: MutableList<NodeConnection> = mutableListOf(),
) {
    fun addNode(node: GraphNode) {
        nodes[node.id] = node
    }

    fun connect(connection: NodeConnection) {
        require(nodes.containsKey(connection.fromNodeId)) { "Unknown source node ${connection.fromNodeId}" }
        require(nodes.containsKey(connection.toNodeId)) { "Unknown target node ${connection.toNodeId}" }
        connections += connection
    }

    fun topologicalOrder(): List<String> {
        val inDegree = nodes.keys.associateWith { id -> connections.count { it.toNodeId == id } }.toMutableMap()
        val queue = ArrayDeque(inDegree.filterValues { it == 0 }.keys)
        val order = mutableListOf<String>()
        while (queue.isNotEmpty()) {
            val current = queue.removeFirst()
            order += current
            connections.filter { it.fromNodeId == current }.forEach { edge ->
                val remaining = (inDegree[edge.toNodeId] ?: 0) - 1
                inDegree[edge.toNodeId] = remaining
                if (remaining == 0) queue.addLast(edge.toNodeId)
            }
        }
        check(order.size == nodes.size) { "Node graph contains a cycle — compositing graphs must be acyclic" }
        return order
    }

    fun evaluate(onNode: (GraphNode) -> Unit) {
        topologicalOrder().forEach { id -> nodes[id]?.let(onNode) }
    }

    fun node(id: String): GraphNode? = nodes[id]
    fun allNodes(): List<GraphNode> = nodes.values.toList()
    fun allConnections(): List<NodeConnection> = connections.toList()
}

// =====================================================================
// SECTION 5 — AI COPILOT (Phase 3)
// =====================================================================

data class BeatMarker(val timeMs: Long, val strength: Float)

data class CopilotSuggestion(
    val description: String,
    val cutPoints: List<Long>,
    val velocityRampSuggestion: List<CurvePoint>,
)

interface AudioSamples {
    val sampleRateHz: Int
    fun amplitudeAt(timeMs: Long): Float
}

object BeatSyncAnalyzer {

    fun detectBeats(
        audio: AudioSamples,
        durationMs: Long,
        windowMs: Long = 20L,
        threshold: Float = 0.6f,
    ): List<BeatMarker> {
        val markers = mutableListOf<BeatMarker>()
        var t = 0L
        var prevAmplitude = 0f
        while (t < durationMs) {
            val amplitude = audio.amplitudeAt(t)
            if (amplitude > threshold && amplitude > prevAmplitude) {
                markers += BeatMarker(timeMs = t, strength = amplitude)
            }
            prevAmplitude = amplitude
            t += windowMs
        }
        return markers
    }

    fun suggestPunchyTransition(beat: BeatMarker, rampWindowMs: Long = 150L): CopilotSuggestion {
        val rampStart = (beat.timeMs - rampWindowMs).coerceAtLeast(0)
        val rampEnd = beat.timeMs + rampWindowMs
        val ramp = listOf(
            CurvePoint(time = rampStart, value = 0.2f, interpolation = InterpolationType.EASE_IN),
            CurvePoint(time = beat.timeMs, value = 1.0f, interpolation = InterpolationType.HOLD),
            CurvePoint(time = rampEnd, value = 0.2f, interpolation = InterpolationType.EASE_OUT),
        )
        return CopilotSuggestion(
            description = "Punchy transition synced to beat at ${beat.timeMs}ms " +
                "(confidence ${"%.0f".format(beat.strength * 100)}%)",
            cutPoints = listOf(beat.timeMs),
            velocityRampSuggestion = ramp,
        )
    }
}

