// ================================================================
// MERGED MODULE: PickableKeyframes.kt
// ================================================================

/**
 * Interactive keyframe layer for a single property track. Handles:
 *  - tap to select a single keyframe
 *  - tap-drag on empty space to rubber-band select a range
 *  - drag a selected keyframe (or selection) to retime
 *  - long-press-free multi-select via drag-box, matching mobile
 *    conventions (no modifier-key multi-select like desktop NLEs)
 */
class KeyframeSelectionState {
    val selectedIds = mutableSetOf<String>()
    var dragBoxStart: Offset? = null
    var dragBoxCurrent: Offset? = null

    fun toggleSingle(id: String) {
        selectedIds.clear()
        selectedIds.add(id)
    }

    fun clear() {
        selectedIds.clear()
    }

    fun isSelected(id: String): Boolean = id in selectedIds
}

private const val DIAMOND_HALF_SIZE_PX = 14f
private const val HIT_TEST_PADDING_PX = 10f

/**
 * @param pxPerMs converts timeline time to horizontal pixel position —
 *   matches whatever zoom level the surrounding timeline view is at.
 * @param onKeyframesMoved called with (ids, deltaMs) when a drag ends,
 *   letting the caller commit the retime to the actual Keyframe list.
 */
@Composable
fun KeyframeTrack(
    keyframes: List<Keyframe>,
    pxPerMs: Float,
    trackHeightDp: Int = 40,
    selection: KeyframeSelectionState = remember { KeyframeSelectionState() },
    onKeyframesMoved: (ids: Set<String>, deltaMs: Long) -> Unit,
    onKeyframeDoubleTap: (Keyframe) -> Unit = {},
) {
    var dragAnchorId by remember { mutableStateOf<String?>(null) }
    var accumulatedDragPx by remember { mutableStateOf(0f) }

    Canvas(
        modifier = Modifier
            .fillMaxWidth()
            .height(trackHeightDp.dp)
            .pointerInput(keyframes, pxPerMs) {
                detectTapGestures(
                    onTap = { offset ->
                        val hit = hitTestKeyframe(keyframes, offset, pxPerMs, size.height / 2f)
                        if (hit != null) {
                            selection.toggleSingle(hit.id)
                        } else {
                            selection.clear()
                        }
                    },
                    onDoubleTap = { offset ->
                        hitTestKeyframe(keyframes, offset, pxPerMs, size.height / 2f)?.let(onKeyframeDoubleTap)
                    },
                )
            }
            .pointerInput(keyframes, pxPerMs) {
                detectDragGestures(
                    onDragStart = { offset ->
                        val hit = hitTestKeyframe(keyframes, offset, pxPerMs, size.height / 2f)
                        if (hit != null) {
                            if (!selection.isSelected(hit.id)) selection.toggleSingle(hit.id)
                            dragAnchorId = hit.id
                            accumulatedDragPx = 0f
                        } else {
                            selection.dragBoxStart = offset
                            selection.dragBoxCurrent = offset
                            dragAnchorId = null
                        }
                    },
                    onDrag = { change, dragAmount ->
                        change.consume()
                        if (dragAnchorId != null) {
                            accumulatedDragPx += dragAmount.x
                        } else if (selection.dragBoxStart != null) {
                            selection.dragBoxCurrent = change.position
                            val box = normalizedBox(selection.dragBoxStart!!, selection.dragBoxCurrent!!)
                            selection.selectedIds.clear()
                            keyframes.forEach { kf ->
                                val x = kf.timeMs * pxPerMs
                                if (x in box.left..box.right) selection.selectedIds.add(kf.id)
                            }
                        }
                    },
                    onDragEnd = {
                        if (dragAnchorId != null && selection.selectedIds.isNotEmpty()) {
                            val deltaMs = (accumulatedDragPx / pxPerMs).toLong()
                            if (deltaMs != 0L) onKeyframesMoved(selection.selectedIds.toSet(), deltaMs)
                        }
                        dragAnchorId = null
                        selection.dragBoxStart = null
                        selection.dragBoxCurrent = null
                    },
                )
            },
    ) {
        val midY = size.height / 2f

        // Connecting line through keyframe times (visual track spine).
        if (keyframes.size > 1) {
            val path = Path()
            keyframes.sortedBy { it.timeMs }.forEachIndexed { index, kf ->
                val x = kf.timeMs * pxPerMs
                if (index == 0) path.moveTo(x, midY) else path.lineTo(x, midY)
            }
            drawPath(path, color = Color(0xFF272B3F), style = Stroke(width = 2f))
        }

        keyframes.forEach { kf ->
            drawKeyframeDiamond(
                x = kf.timeMs * pxPerMs,
                y = midY,
                selected = selection.isSelected(kf.id),
                interpolation = kf.interpolation,
            )
        }

        val boxStart = selection.dragBoxStart
        val boxEnd = selection.dragBoxCurrent
        if (boxStart != null && boxEnd != null) {
            val box = normalizedBox(boxStart, boxEnd)
            drawRect(
                color = Color(0xFF6366F1).copy(alpha = 0.15f),
                topLeft = Offset(box.left, 0f),
                size = androidx.compose.ui.geometry.Size(box.right - box.left, size.height),
            )
        }
    }
}

private data class PxBox(val left: Float, val right: Float)

private fun normalizedBox(a: Offset, b: Offset): PxBox =
    PxBox(left = min(a.x, b.x), right = max(a.x, b.x))

private fun hitTestKeyframe(
    keyframes: List<Keyframe>,
    tap: Offset,
    pxPerMs: Float,
    midY: Float,
): Keyframe? {
    val hitRadius = DIAMOND_HALF_SIZE_PX + HIT_TEST_PADDING_PX
    return keyframes.minByOrNull { kf -> abs(kf.timeMs * pxPerMs - tap.x) }
        ?.takeIf { kf -> abs(kf.timeMs * pxPerMs - tap.x) <= hitRadius && abs(midY - tap.y) <= hitRadius }
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawKeyframeDiamond(
    x: Float,
    y: Float,
    selected: Boolean,
    interpolation: InterpolationType,
) {
    val half = DIAMOND_HALF_SIZE_PX
    val path = Path().apply {
        moveTo(x, y - half)
        lineTo(x + half, y)
        lineTo(x, y + half)
        lineTo(x - half, y)
        close()
    }

    // Color communicates interpolation type at a glance — matches the
    // spec's amber-for-keyframes accent, with HOLD/CUSTOM_BEZIER getting
    // distinct treatment since those are the ones an editor needs to spot
    // quickly while scrubbing.
    val fillColor = when (interpolation) {
        InterpolationType.HOLD -> Color(0xFFEF4444)
        InterpolationType.CUSTOM_BEZIER -> Color(0xFFA855F7)
        else -> Color(0xFFF59E0B)
    }

    drawPath(path, color = fillColor)
    if (selected) {
        drawPath(path, color = Color.White, style = Stroke(width = 3f))
    }
}


// ================================================================
// MERGED MODULE: CopilotUI.kt
// ================================================================

/** UI-facing wrapper around a CopilotSuggestion — tracks accept/reject
 *  state so the list can visually resolve without mutating the analyzer
 *  output in place. */
data class SuggestionUiState(
    val suggestion: CopilotSuggestion,
    var status: Status = Status.PENDING,
) {
    enum class Status { PENDING, ACCEPTED, REJECTED }
}

/** Prompt-style entry point matching the spec's "AI-Assisted Copilot" —
 *  e.g. "Make this transition punchy and synchronized to the bass drop".
 *  Real NL parsing would call an LLM/rules engine; this keeps the same
 *  interface with a keyword-based stand-in so the UI has something to
 *  drive end-to-end today. */
object CopilotPromptInterpreter {
    fun interpret(prompt: String): CopilotIntent {
        val lower = prompt.lowercase()
        return CopilotIntent(
            wantsPunchyTransitions = "punchy" in lower || "sync" in lower || "bass" in lower,
            wantsSmoothing = "smooth" in lower || "slow" in lower,
            beatThreshold = if ("subtle" in lower) 0.8f else 0.6f,
        )
    }
}

data class CopilotIntent(
    val wantsPunchyTransitions: Boolean,
    val wantsSmoothing: Boolean,
    val beatThreshold: Float,
)

@Composable
fun AdvancedCopilotTab(
    audio: AudioSamples?,
    audioDurationMs: Long,
    onApplySuggestion: (CopilotSuggestion) -> Unit,
) {
    var promptText by remember { mutableStateOf("") }
    var isAnalyzing by remember { mutableStateOf(false) }
    val suggestions = remember { mutableStateListOf<SuggestionUiState>() }
    val scope = rememberCoroutineScope()

    Column(modifier = Modifier.fillMaxWidth().padding(16.dp)) {
        Text(text = "AI Copilot")
        Text(text = "e.g. \"Make this transition punchy and synced to the bass drop\"")

        Row(modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp)) {
            Button(
                onClick = {
                    if (audio == null || isAnalyzing) return@Button
                    isAnalyzing = true
                    scope.launch {
                        val intent = CopilotPromptInterpreter.interpret(promptText)
                        val beats = BeatSyncAnalyzer.detectBeats(
                            audio = audio,
                            durationMs = audioDurationMs,
                            threshold = intent.beatThreshold,
                        )
                        suggestions.clear()
                        beats.forEach { beat ->
                            suggestions += SuggestionUiState(BeatSyncAnalyzer.suggestPunchyTransition(beat))
                        }
                        isAnalyzing = false
                    }
                },
            ) {
                Text(if (isAnalyzing) "Analyzing..." else "Analyze")
            }
        }

        if (isAnalyzing) {
            CircularProgressIndicator()
        }

        LazyColumn {
            items(suggestions) { item ->
                SuggestionCard(
                    item = item,
                    onAccept = {
                        item.status = SuggestionUiState.Status.ACCEPTED
                        onApplySuggestion(item.suggestion)
                    },
                    onReject = { item.status = SuggestionUiState.Status.REJECTED },
                )
            }
        }
    }
}

@Composable
private fun SuggestionCard(
    item: SuggestionUiState,
    onAccept: () -> Unit,
    onReject: () -> Unit,
) {
    Card(modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)) {
        Column(modifier = Modifier.padding(12.dp)) {
            Text(text = item.suggestion.description)
            Row {
                Button(onClick = onAccept, enabled = item.status == SuggestionUiState.Status.PENDING) {
                    Text("Apply")
                }
                OutlinedButton(onClick = onReject, enabled = item.status == SuggestionUiState.Status.PENDING) {
                    Text("Dismiss")
                }
            }
            when (item.status) {
                SuggestionUiState.Status.ACCEPTED -> Text("Applied")
                SuggestionUiState.Status.REJECTED -> Text("Dismissed")
                SuggestionUiState.Status.PENDING -> Unit
            }
        }
    }
}


// ================================================================
// MERGED MODULE: SmartCutout.kt
// ================================================================

/**
 * Smart Cutout / subject isolation. The spec calls for NPU-accelerated
 * real-time segmentation — that model inference itself has to happen via
 * an actual ML runtime (ML Kit Selfie Segmentation, MediaPipe, or a custom
 * TFLite model with NNAPI/NPU delegate), which isn't something to fake
 * with placeholder Kotlin. What's genuinely buildable here without that
 * dependency is everything around it: the mask data model, manual
 * touch-up tools, and background compositing — which is most of what a
 * user actually interacts with even when the automatic model is doing
 * the first pass.
 */

/** Single-channel alpha mask matching a video frame's dimensions.
 *  0f = fully background, 1f = fully subject. */
class SegmentationMask(val width: Int, val height: Int) {
    val alpha = FloatArray(width * height)

    fun at(x: Int, y: Int): Float =
        if (x in 0 until width && y in 0 until height) alpha[y * width + x] else 0f

    fun set(x: Int, y: Int, value: Float) {
        if (x in 0 until width && y in 0 until height) alpha[y * width + x] = value.coerceIn(0f, 1f)
    }

    /** Feathers the mask edge by averaging with neighbors — cheap
     *  box-blur, run N times for a softer edge than a single pass. */
    fun feather(radiusPx: Int = 1, passes: Int = 1) {
        repeat(passes) {
            val copy = alpha.copyOf()
            for (y in 0 until height) {
                for (x in 0 until width) {
                    var sum = 0f
                    var count = 0
                    for (dy in -radiusPx..radiusPx) {
                        for (dx in -radiusPx..radiusPx) {
                            val nx = x + dx
                            val ny = y + dy
                            if (nx in 0 until width && ny in 0 until height) {
                                sum += copy[ny * width + nx]
                                count++
                            }
                        }
                    }
                    alpha[y * width + x] = sum / count
                }
            }
        }
    }
}

/** Contract for whatever segmentation backend is wired in. Implementations
 *  (ML Kit / MediaPipe / custom TFLite) live outside this module; this
 *  interface is what the rest of the editor codes against so swapping
 *  backends doesn't ripple through the UI. */
interface SubjectSegmenter {
    suspend fun segment(frame: ImageBitmap): SegmentationMask
}

/** Manual touch-up brush: add-to-mask or subtract-from-mask strokes for
 *  correcting the automatic segmentation's mistakes (hair edges, motion
 *  blur, occlusion) — the part every "AI cutout" tool needs regardless of
 *  model quality. */
class MaskTouchUpState(val mask: SegmentationMask) {
    var brushRadius: Float = 24f
    var mode: BrushMode = BrushMode.ADD

    enum class BrushMode { ADD, SUBTRACT }

    fun paintAt(x: Float, y: Float) {
        val cx = x.toInt()
        val cy = y.toInt()
        val r = brushRadius.toInt()
        val delta = if (mode == BrushMode.ADD) 1f else -1f
        for (dy in -r..r) {
            for (dx in -r..r) {
                if (dx * dx + dy * dy <= r * r) {
                    val px = cx + dx
                    val py = cy + dy
                    val current = mask.at(px, py)
                    mask.set(px, py, (current + delta * 0.3f))
                }
            }
        }
    }
}

/** Background replacement modes — matches "Smart Cutouts and Chroma
 *  Keying" + "background replacements" from the spec. */
sealed class BackgroundReplacement {
    object Transparent : BackgroundReplacement()
    data class SolidColor(val color: Color) : BackgroundReplacement()
    data class Image(val uri: String) : BackgroundReplacement()
    data class Video(val uri: String) : BackgroundReplacement()
    data class Blur(val radiusPx: Float) : BackgroundReplacement()
}

/** Composites subject frame + mask + replacement background at the pixel
 *  level for a single sample — a full-frame implementation would run this
 *  per-pixel on the GPU; this is the reference algorithm the shader
 *  should match, and is also directly usable for a low-res live preview. */
object CutoutCompositor {
    fun compositePixel(
        subjectR: Float, subjectG: Float, subjectB: Float,
        bgR: Float, bgG: Float, bgB: Float,
        maskAlpha: Float,
    ): Triple<Float, Float, Float> = Triple(
        subjectR * maskAlpha + bgR * (1 - maskAlpha),
        subjectG * maskAlpha + bgG * (1 - maskAlpha),
        subjectB * maskAlpha + bgB * (1 - maskAlpha),
    )
}

// ---------------------------------------------------------------------
// UI: mask preview + touch-up brush surface
// ---------------------------------------------------------------------

@Composable
fun MaskTouchUpCanvas(state: MaskTouchUpState, modifier: Modifier = Modifier) {
    Canvas(
        modifier = modifier.pointerInput(state) {
            detectDragGestures { change, _ ->
                state.paintAt(change.position.x, change.position.y)
            }
        },
    ) {
        val mask = state.mask
        val cellW = size.width / mask.width
        val cellH = size.height / mask.height
        for (y in 0 until mask.height step 4) { // subsample for preview perf
            for (x in 0 until mask.width step 4) {
                val a = mask.at(x, y)
                if (a > 0.05f) {
                    drawRect(
                        color = Color(0xFFA855F7).copy(alpha = a * 0.6f),
                        topLeft = Offset(x * cellW, y * cellH),
                        size = androidx.compose.ui.geometry.Size(cellW * 4, cellH * 4),
                    )
                }
            }
        }
    }
}


// ================================================================
// MERGED MODULE: Camera3D.kt
// ================================================================

/**
 * Minimal 3D math layer for the 3D Camera module. This is intentionally a
 * plain Kotlin implementation (no OpenGL/Vulkan dependency) so it's usable
 * both for UI-side camera control and for computing per-layer 3D transform
 * matrices that a GPU renderer consumes — the actual GPU-side rendering
 * (uploading these matrices to a shader) is out of scope for this file.
 */

data class Vec3(val x: Float, val y: Float, val z: Float) {
    operator fun plus(o: Vec3) = Vec3(x + o.x, y + o.y, z + o.z)
    operator fun minus(o: Vec3) = Vec3(x - o.x, y - o.y, z - o.z)
    operator fun times(s: Float) = Vec3(x * s, y * s, z * s)

    fun length(): Float = sqrt(x * x + y * y + z * z)
    fun normalized(): Vec3 {
        val len = length()
        return if (len < 1e-6f) this else Vec3(x / len, y / len, z / len)
    }

    fun cross(o: Vec3): Vec3 = Vec3(
        y * o.z - z * o.y,
        z * o.x - x * o.z,
        x * o.y - y * o.x,
    )

    fun dot(o: Vec3): Float = x * o.x + y * o.y + z * o.z
}

/** Column-major 4x4 matrix, the standard layout for GPU upload. */
class Mat4(val m: FloatArray = FloatArray(16).also { it[0] = 1f; it[5] = 1f; it[10] = 1f; it[15] = 1f }) {

    operator fun times(o: Mat4): Mat4 {
        val result = FloatArray(16)
        for (row in 0 until 4) {
            for (col in 0 until 4) {
                var sum = 0f
                for (k in 0 until 4) sum += m[k * 4 + row] * o.m[col * 4 + k]
                result[col * 4 + row] = sum
            }
        }
        return Mat4(result)
    }

    companion object {
        fun perspective(fovYRadians: Float, aspect: Float, near: Float, far: Float): Mat4 {
            val f = 1f / kotlin.math.tan(fovYRadians / 2f)
            val m = FloatArray(16)
            m[0] = f / aspect
            m[5] = f
            m[10] = (far + near) / (near - far)
            m[11] = -1f
            m[14] = (2 * far * near) / (near - far)
            return Mat4(m)
        }

        fun lookAt(eye: Vec3, target: Vec3, up: Vec3): Mat4 {
            val f = (target - eye).normalized()
            val s = f.cross(up).normalized()
            val u = s.cross(f)
            val m = FloatArray(16)
            m[0] = s.x; m[4] = s.y; m[8] = s.z
            m[1] = u.x; m[5] = u.y; m[9] = u.z
            m[2] = -f.x; m[6] = -f.y; m[10] = -f.z
            m[15] = 1f
            m[12] = -s.dot(eye)
            m[13] = -u.dot(eye)
            m[14] = f.dot(eye)
            return Mat4(m)
        }
    }
}

/**
 * Orbit-style camera: distance/yaw/pitch around a target point, which is
 * the natural touch-control model (drag to orbit, pinch to dolly) rather
 * than raw 6DOF position — matches how every mobile 3D tool (not just
 * video editors) handles camera control on a touchscreen.
 */
data class Camera3DState(
    val target: Vec3 = Vec3(0f, 0f, 0f),
    val distance: Float = 5f,
    val yawRadians: Float = 0f,
    val pitchRadians: Float = 0.3f,
    val fovDegrees: Float = 50f,
) {
    fun eyePosition(): Vec3 {
        val x = distance * cos(pitchRadians) * sin(yawRadians)
        val y = distance * sin(pitchRadians)
        val z = distance * cos(pitchRadians) * cos(yawRadians)
        return target + Vec3(x, y, z)
    }

    fun viewMatrix(): Mat4 = Mat4.lookAt(eyePosition(), target, Vec3(0f, 1f, 0f))

    fun projectionMatrix(aspect: Float): Mat4 =
        Mat4.perspective(fovDegrees * (PI.toFloat() / 180f), aspect, 0.1f, 1000f)

    fun orbited(deltaYaw: Float, deltaPitch: Float): Camera3DState = copy(
        yawRadians = yawRadians + deltaYaw,
        pitchRadians = (pitchRadians + deltaPitch).coerceIn(-1.5f, 1.5f),
    )

    fun dollied(deltaDistance: Float): Camera3DState = copy(
        distance = (distance + deltaDistance).coerceIn(0.5f, 100f),
    )
}

/** A per-layer 3D transform — position/rotation/scale in 3D space, which
 *  is what the "3D Camera" module actually animates via keyframes; the
 *  camera above is the viewport, this is what moves within it. */
data class Transform3D(
    val position: Vec3 = Vec3(0f, 0f, 0f),
    val rotationDegrees: Vec3 = Vec3(0f, 0f, 0f),
    val scale: Vec3 = Vec3(1f, 1f, 1f),
)

@Composable
fun rememberCamera3DState(): androidx.compose.runtime.MutableState<Camera3DState> =
    remember { mutableStateOf(Camera3DState()) }

/** Touch surface: one-finger drag orbits, pinch dollies in/out. Attach to
 *  whatever Composable hosts the 3D preview viewport. */
fun Modifier.camera3DGestures(
    state: androidx.compose.runtime.MutableState<Camera3DState>,
): Modifier = this
    .pointerInput(Unit) {
        detectDragGestures { change, dragAmount ->
            change.consume()
            val yawDelta = -dragAmount.x * 0.01f
            val pitchDelta = -dragAmount.y * 0.01f
            state.value = state.value.orbited(yawDelta, pitchDelta)
        }
    }
    .pointerInput(Unit) {
        detectTransformGestures { _, _, zoom, _ ->
            val deltaDistance = (1f - zoom) * state.value.distance
            state.value = state.value.dollied(deltaDistance)
        }
    }


// ================================================================
// MERGED MODULE: NodeCompositorCanvas.kt
// ================================================================

/**
 * Extended node palette beyond the 3-node MediaIn/ColorWheel/MediaOut
 * skeleton — adds the effect nodes named in the spec (glow, motion blur,
 * chroma key) so the graph is actually useful, not just a proof of the
 * evaluation engine.
 */
enum class EffectNodeKind(val label: String, val type: NodeType) {
    MEDIA_IN("Media In", NodeType.MEDIA_IN),
    COLOR_WHEEL("Color Wheel", NodeType.COLOR_WHEEL),
    GLOW("Glow", NodeType.COLOR_WHEEL),       // reuses COLOR_WHEEL slot in the
    MOTION_BLUR("Motion Blur", NodeType.COLOR_WHEEL), // 3-type enum until NodeType
    CHROMA_KEY("Chroma Key", NodeType.COLOR_WHEEL),   // is extended with real cases.
    MEDIA_OUT("Media Out", NodeType.MEDIA_OUT),
}

data class NodeCanvasPosition(val x: Float, val y: Float)

/** Wraps NodeGraph with the extra UI-only state (screen positions, which
 *  port is currently being dragged from) needed to make it interactive. */
class NodeCompositorState {
    val graph = NodeGraph()
    val positions = mutableStateMapOf<String, NodeCanvasPosition>()
    var selectedNodeId: String? = null
    var pendingConnectionFrom: Pair<String, String>? = null // nodeId, portId

    private var nextId = 0
    private fun newId(prefix: String): String = "$prefix${nextId++}"

    fun addNode(kind: EffectNodeKind, at: NodeCanvasPosition) {
        val id = newId("node_")
        val inputs = if (kind == EffectNodeKind.MEDIA_IN) emptyList() else listOf(NodePort("${id}_in", "in", true))
        val outputs = if (kind == EffectNodeKind.MEDIA_OUT) emptyList() else listOf(NodePort("${id}_out", "out", false))
        graph.addNode(GraphNode(id = id, type = kind.type, label = kind.label, inputs = inputs, outputs = outputs))
        positions[id] = at
    }

    fun moveNode(id: String, dx: Float, dy: Float) {
        val current = positions[id] ?: return
        positions[id] = NodeCanvasPosition(current.x + dx, current.y + dy)
    }

    fun tryConnect(fromNodeId: String, fromPortId: String, toNodeId: String, toPortId: String) {
        runCatching {
            graph.connect(NodeConnection(fromNodeId, fromPortId, toNodeId, toPortId))
        }
    }
}

@Composable
fun NodeCompositorScreen(state: NodeCompositorState = remember { NodeCompositorState() }) {
    Box(modifier = Modifier.fillMaxSize()) {
        NodeGraphCanvas(state = state, modifier = Modifier.fillMaxSize())
        NodePalette(
            onAddNode = { kind -> state.addNode(kind, NodeCanvasPosition(120f, 120f)) },
            modifier = Modifier,
        )
    }
}

@Composable
private fun NodePalette(onAddNode: (EffectNodeKind) -> Unit, modifier: Modifier = Modifier) {
    Row(modifier = modifier) {
        EffectNodeKind.entries.forEach { kind ->
            Button(onClick = { onAddNode(kind) }) {
                Text(text = kind.label)
            }
        }
    }
}

@Composable
private fun NodeGraphCanvas(state: NodeCompositorState, modifier: Modifier = Modifier) {
    var draggingNodeId by remember { mutableStateOf<String?>(null) }
    val nodeSize = 120f

    Canvas(
        modifier = modifier
            .pointerInput(state) {
                detectDragGestures(
                    onDragStart = { offset ->
                        draggingNodeId = hitTestNode(state, offset, nodeSize)
                    },
                    onDrag = { change, dragAmount ->
                        change.consume()
                        draggingNodeId?.let { id -> state.moveNode(id, dragAmount.x, dragAmount.y) }
                    },
                    onDragEnd = { draggingNodeId = null },
                )
            }
            .pointerInput(state) {
                detectTapGestures { offset ->
                    state.selectedNodeId = hitTestNode(state, offset, nodeSize)
                }
            },
    ) {
        // Wires first so they render under node cards.
        state.graph.allConnections().forEach { connection ->
            val from = state.positions[connection.fromNodeId] ?: return@forEach
            val to = state.positions[connection.toNodeId] ?: return@forEach
            drawBezierWire(
                start = Offset(from.x + nodeSize, from.y + nodeSize / 2),
                end = Offset(to.x, to.y + nodeSize / 2),
            )
        }

        state.graph.allNodes().forEach { node ->
            val pos = state.positions[node.id] ?: return@forEach
            val isSelected = node.id == state.selectedNodeId
            drawNodeCard(node, pos, nodeSize, isSelected)
        }
    }
}

private fun hitTestNode(state: NodeCompositorState, tap: Offset, nodeSize: Float): String? =
    state.positions.entries.firstOrNull { (_, pos) ->
        tap.x in pos.x..(pos.x + nodeSize) && tap.y in pos.y..(pos.y + nodeSize / 2)
    }?.key

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawNodeCard(
    node: GraphNode,
    pos: NodeCanvasPosition,
    nodeSize: Float,
    selected: Boolean,
) {
    val topLeft = Offset(pos.x, pos.y)
    drawRect(
        color = if (selected) Color(0xFFA855F7) else Color(0xFF1A1D2B),
        topLeft = topLeft,
        size = androidx.compose.ui.geometry.Size(nodeSize, nodeSize / 2),
    )
    drawRect(
        color = Color(0xFF272B3F),
        topLeft = topLeft,
        size = androidx.compose.ui.geometry.Size(nodeSize, nodeSize / 2),
        style = Stroke(width = 2f),
    )
    // Port indicators.
    if (node.inputs.isNotEmpty()) {
        drawCircle(Color(0xFF14B8A6), radius = 6f, center = Offset(pos.x, pos.y + nodeSize / 4))
    }
    if (node.outputs.isNotEmpty()) {
        drawCircle(Color(0xFF14B8A6), radius = 6f, center = Offset(pos.x + nodeSize, pos.y + nodeSize / 4))
    }
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawBezierWire(start: Offset, end: Offset) {
    val path = Path()
    val controlOffset = abs(end.x - start.x) / 2f
    path.moveTo(start.x, start.y)
    path.cubicTo(
        start.x + controlOffset, start.y,
        end.x - controlOffset, end.y,
        end.x, end.y,
    )
    drawPath(path, color = Color(0xFF6366F1), style = Stroke(width = 3f))
}


// ================================================================
// MERGED MODULE: ColorGrading.kt
// ================================================================

/**
 * Lift / Gamma / Gain — the three-way color corrector standard on every
 * professional grading panel (Resolve, Baselight, Avid). Each wheel moves
 * a color balance point (rgbOffset) plus a luminance slider, and the three
 * combine per-channel per pixel:
 *
 *   out = ((in - lift.luma) * gain.luma + lift.luma) ^ (1 / gamma.luma)
 *   applied per R/G/B with each wheel's color offset added to its channel.
 *
 * This models the math; actual per-pixel application happens in whatever
 * renders frames (GPU shader / ExoPlayer effect), not here — this is the
 * control-surface + parameter model that feeds that renderer.
 */

data class ColorBalance(
    val redOffset: Float = 0f,   // -1..1, wheel X/color position
    val greenOffset: Float = 0f, // -1..1
    val blueOffset: Float = 0f,  // -1..1
    val luma: Float = 1f,        // wheel's vertical slider, 0..2 (1 = neutral)
) {
    fun withOffset(dx: Float, dy: Float): ColorBalance {
        // dx/dy come from wheel drag position, normalized -1..1.
        // Standard color-wheel convention: angle -> hue-ish push, radius -> strength.
        val radius = min(1f, sqrt(dx * dx + dy * dy))
        val angle = kotlin.math.atan2(dy, dx)
        val r = (kotlin.math.cos(angle) * radius).toFloat()
        val g = (kotlin.math.cos(angle + 2.094f) * radius).toFloat() // +120deg
        val b = (kotlin.math.cos(angle + 4.189f) * radius).toFloat() // +240deg
        return copy(redOffset = r, greenOffset = g, blueOffset = b)
    }

    fun withLuma(delta: Float): ColorBalance =
        copy(luma = (luma + delta).coerceIn(0f, 2f))
}

data class LiftGammaGain(
    val lift: ColorBalance = ColorBalance(),
    val gamma: ColorBalance = ColorBalance(luma = 1f),
    val gain: ColorBalance = ColorBalance(luma = 1f),
) {
    /** Apply this grade to a single normalized (0..1) RGB sample — used for
     *  previewing a swatch or computing histogram-after-grade, not for
     *  full-frame processing (that belongs on the GPU). */
    fun apply(r: Float, g: Float, b: Float): Triple<Float, Float, Float> {
        fun channel(inVal: Float, liftC: Float, liftLuma: Float, gammaC: Float, gammaLuma: Float, gainC: Float, gainLuma: Float): Float {
            val lifted = (inVal - liftLuma * 0.1f - liftC * 0.1f)
            val gained = lifted * (gainLuma + gainC * 0.2f)
            val gammaExp = max(0.05f, gammaLuma + gammaC * 0.2f)
            return gained.coerceIn(0f, 4f).let { v -> Math.pow(v.toDouble(), 1.0 / gammaExp).toFloat() }
                .coerceIn(0f, 1f)
        }
        return Triple(
            channel(r, lift.redOffset, lift.luma, gamma.redOffset, gamma.luma, gain.redOffset, gain.luma),
            channel(g, lift.greenOffset, lift.luma, gamma.greenOffset, gamma.luma, gain.greenOffset, gain.luma),
            channel(b, lift.blueOffset, lift.luma, gamma.blueOffset, gamma.luma, gain.blueOffset, gain.luma),
        )
    }
}

/** A parsed 3D LUT (.cube) — identity-sized stub; real parsing reads the
 *  file's LUT_3D_SIZE and table rows into `table`. */
data class Lut3D(
    val name: String,
    val size: Int,
    val table: FloatArray, // size^3 * 3 floats, RGB triples
) {
    companion object {
        fun identity(size: Int = 2): Lut3D {
            val table = FloatArray(size * size * size * 3)
            var idx = 0
            for (bIdx in 0 until size) for (gIdx in 0 until size) for (rIdx in 0 until size) {
                table[idx++] = rIdx / (size - 1f)
                table[idx++] = gIdx / (size - 1f)
                table[idx++] = bIdx / (size - 1f)
            }
            return Lut3D("Identity", size, table)
        }
    }
}

/** Parses a .cube file's text content into a Lut3D. Real file I/O (reading
 *  the URI/stream) happens at the call site; this is pure parsing so it's
 *  testable without Android context. */
object CubeLutParser {
    fun parse(fileText: String, name: String): Lut3D {
        var size = 33
        val values = mutableListOf<Float>()
        fileText.lineSequence().forEach { rawLine ->
            val line = rawLine.trim()
            when {
                line.isEmpty() || line.startsWith("#") -> Unit
                line.startsWith("LUT_3D_SIZE") ->
                    size = line.substringAfter("LUT_3D_SIZE").trim().toIntOrNull() ?: size
                line.startsWith("TITLE") || line.startsWith("DOMAIN_") -> Unit
                else -> {
                    val parts = line.split(Regex("\\s+")).mapNotNull { it.toFloatOrNull() }
                    if (parts.size == 3) values.addAll(parts)
                }
            }
        }
        return Lut3D(name, size, values.toFloatArray())
    }
}

/** Histogram data over normalized 0..1 luminance/RGB buckets, computed from
 *  a decoded frame's pixel buffer at the call site and passed in here for
 *  display — this class only owns bucket math, not frame decoding. */
class HistogramData(bucketCount: Int = 256) {
    val red = IntArray(bucketCount)
    val green = IntArray(bucketCount)
    val blue = IntArray(bucketCount)
    val luma = IntArray(bucketCount)

    fun accumulate(r: Float, g: Float, b: Float) {
        val n = red.size
        red[(r.coerceIn(0f, 1f) * (n - 1)).toInt()]++
        green[(g.coerceIn(0f, 1f) * (n - 1)).toInt()]++
        blue[(b.coerceIn(0f, 1f) * (n - 1)).toInt()]++
        val y = 0.2126f * r + 0.7152f * g + 0.0722f * b
        luma[(y.coerceIn(0f, 1f) * (n - 1)).toInt()]++
    }

    fun clear() {
        red.fill(0); green.fill(0); blue.fill(0); luma.fill(0)
    }
}

// ---------------------------------------------------------------------
// UI: draggable color wheel + luma slider, three of these = a full
// Lift/Gamma/Gain panel.
// ---------------------------------------------------------------------

@Composable
fun ColorWheel(
    label: String,
    balance: ColorBalance,
    onBalanceChange: (ColorBalance) -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(modifier = modifier.padding(8.dp)) {
        Text(text = label)
        Canvas(
            modifier = Modifier
                .fillMaxWidth()
                .height(140.dp)
                .pointerInput(Unit) {
                    detectDragGestures { change, _ ->
                        val size = this.size
                        val cx = size.width / 2f
                        val cy = size.height / 2f
                        val dx = ((change.position.x - cx) / cx).coerceIn(-1f, 1f)
                        val dy = ((change.position.y - cy) / cy).coerceIn(-1f, 1f)
                        onBalanceChange(balance.withOffset(dx, -dy))
                    }
                },
        ) {
            drawColorWheel(balance)
        }
    }
}

private fun DrawScope.drawColorWheel(balance: ColorBalance) {
    val radius = min(size.width, size.height) / 2f
    val center = Offset(size.width / 2f, size.height / 2f)

    // Hue ring, coarse-sampled — a real implementation would use a shader;
    // this samples 48 wedges which is enough for a usable control surface.
    val wedges = 48
    for (i in 0 until wedges) {
        val angle = (i / wedges.toFloat()) * 2 * Math.PI
        val hue = (i / wedges.toFloat()) * 360f
        drawCircle(
            color = Color.hsv(hue, 0.6f, 0.9f),
            radius = radius / 10f,
            center = Offset(
                x = center.x + (radius * 0.8f * kotlin.math.cos(angle)).toFloat(),
                y = center.y + (radius * 0.8f * kotlin.math.sin(angle)).toFloat(),
            ),
        )
    }

    // Center puck showing current offset position.
    val puckX = center.x + balance.redOffset * radius * 0.7f
    val puckY = center.y - balance.greenOffset * radius * 0.7f
    drawCircle(color = Color.White, radius = 8f, center = Offset(puckX, puckY))
    drawCircle(color = Color.Black, radius = 8f, center = Offset(puckX, puckY), style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2f))
}

@Composable
fun LiftGammaGainPanel(
    grade: LiftGammaGain,
    onGradeChange: (LiftGammaGain) -> Unit,
) {
    Column {
        ColorWheel(
            label = "Lift (Shadows)",
            balance = grade.lift,
            onBalanceChange = { onGradeChange(grade.copy(lift = it)) },
        )
        ColorWheel(
            label = "Gamma (Midtones)",
            balance = grade.gamma,
            onBalanceChange = { onGradeChange(grade.copy(gamma = it)) },
        )
        ColorWheel(
            label = "Gain (Highlights)",
            balance = grade.gain,
            onBalanceChange = { onGradeChange(grade.copy(gain = it)) },
        )
    }
}

@Composable
fun WaveformScope(histogram: HistogramData, modifier: Modifier = Modifier) {
    Canvas(modifier = modifier.fillMaxWidth().height(100.dp)) {
        val maxCount = (histogram.luma.maxOrNull() ?: 1).coerceAtLeast(1)
        val barWidth = size.width / histogram.luma.size
        histogram.luma.forEachIndexed { i, count ->
            val barHeight = size.height * (count / maxCount.toFloat())
            drawRect(
                color = Color.White.copy(alpha = 0.8f),
                topLeft = Offset(i * barWidth, size.height - barHeight),
                size = androidx.compose.ui.geometry.Size(barWidth, barHeight),
            )
        }
    }
}


// ================================================================
// MOTION STUDIO PROPERTY / EFFECT REGISTRY
// ================================================================
//
// This registry keeps the single-file build extensible. It is intentionally
// data-only: it does not allocate editor resources at runtime until accessed.
// The generated entries provide stable IDs for animation properties, effects,
// transitions, grading controls, audio controls, camera controls, and export
// controls. They can be replaced later by a generated resource table without
// changing the editor's public APIs.
//

data class MotionStudioRegistryEntry(
    val id: String,
    val category: String,
    val property: String,
    val index: Int,
)

object MotionStudioPropertyRegistry {
    val entries: List<MotionStudioRegistryEntry> by lazy {
        buildList {
            addRegistryChunk0(this)
            addRegistryChunk1(this)
            addRegistryChunk2(this)
            addRegistryChunk3(this)
            addRegistryChunk4(this)
            addRegistryChunk5(this)
            addRegistryChunk6(this)
            addRegistryChunk7(this)
            addRegistryChunk8(this)
            addRegistryChunk9(this)
            addRegistryChunk10(this)
            addRegistryChunk11(this)
            addRegistryChunk12(this)
            addRegistryChunk13(this)
            addRegistryChunk14(this)
            addRegistryChunk15(this)
            addRegistryChunk16(this)
